// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.deal(address(this), amount);
        vm.deal(address(c), amount); // ensure c can pay
        Recorder r = new Recorder();
        c.sendMoney(address(r), amount);
        assertTrue(r.received() == amount);
    }

    receive() external payable {}
}

contract Recorder {
    uint256 public received;
    fallback() external payable { received += msg.value; }
}
